// Snugcase — original packing puzzle. Drag oddly shaped things into the case, tap to rotate, fill every slot, snap the lid.
// Levels are generated by tiling the case interior into pieces (seeded), so every case has a solution.
import { createUI, store, buzz, tone } from './kit/hc.js';
import { flow } from './kit/flow.js';
import { daily } from './kit/daily.js';
import { board as scoreboard } from './kit/board.js';
import { demo } from './kit/demo.js';
import { css, cardTheme, startCard, fx2d, chime, arp, soft, todayKey } from './calm.js';
import { outline, roundPath, classify, ITEMS, drawItem, fillOf, shade, INK } from './art.js';

const NAME = 'Snugcase: Packing Puzzle';
const S = store('snugcase');
const F = flow('snugcase');
const ui = createUI({ title: 'Snugcase', hint: 'Tap to pack', hand: '', score: false });
cardTheme({ accent: '#ff6f61', font: "'Baloo 2',system-ui,sans-serif", serif: "'Baloo 2',system-ui,sans-serif" });
const D = daily('snugcase', ui, { name: NAME });
const B = scoreboard({ game: 'snugcase', label: 'Boxes packed', limits: { maxRun: 1, maxPerSec: 0.5 }, mode: 'sum', corner: 'tl' });
const fx = fx2d(11);
const doneToday = S.get('daily_' + todayKey(), null);
startCard(ui, D, { kicker: D.isDaily ? 'Daily packing puzzle' : 'Packing puzzle', doneLine: doneToday ? 'Packed today ✓' : null });
if (D.isDaily) ui.els.win.querySelector('p').innerHTML = 'Daily box<span data-l hidden></span>';
ui.els.win.querySelector('h1').textContent = 'All packed!';

css(`
body{background:#ffe9d6}
.hc-card,.hc-card.dim{background:linear-gradient(180deg,rgba(58,44,77,.55),rgba(58,44,77,.72))}
.hc-card h1{font-weight:800;letter-spacing:0}
.hc-top{z-index:6}
.hc-top .hc-lvl{box-shadow:0 3px 0 rgba(58,44,77,.25);border:2.5px solid ${INK}}
.hc-top .hc-lvl.next{background:#fff;color:${INK}}
.hc-top .hc-bar{background:#fff;border:2.5px solid ${INK};height:16px}
.hc-sub{top:calc(56px + env(safe-area-inset-top));color:${INK};font-weight:800;font-size:17px;letter-spacing:.5px;text-shadow:none;opacity:.85}
#sc{position:fixed;inset:0;width:100%;height:100%;z-index:1;touch-action:none}
.sbtn{position:fixed;z-index:4;width:54px;height:54px;border-radius:50%;background:#fff;border:3px solid ${INK};box-shadow:0 4px 0 ${INK};display:grid;place-items:center;cursor:pointer;padding:0}
.sbtn:active{transform:translateY(3px);box-shadow:0 1px 0 ${INK}}
.sbtn svg{width:26px;height:26px;stroke:${INK};fill:none;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.hc-pop{color:#fff!important;-webkit-text-stroke:2px ${INK};paint-order:stroke fill;text-shadow:0 4px 0 ${INK}!important}
`);
const cv = document.createElement('canvas'); cv.id = 'sc'; document.body.prepend(cv);
const g = cv.getContext('2d');
const mkBtn = (svg) => { const b = document.createElement('button'); b.className = 'sbtn'; b.innerHTML = svg; b.addEventListener('pointerdown', e => e.stopPropagation()); document.body.appendChild(b); return b; };
const undoBtn = mkBtn('<svg viewBox="0 0 24 24"><path d="M9 14L4 9l5-5"/><path d="M4 9h10a6 6 0 010 12h-3"/></svg>');
const resetBtn = mkBtn('<svg viewBox="0 0 24 24"><path d="M3 12a9 9 0 109-9 9.7 9.7 0 00-6.7 2.8L3 8"/><path d="M3 3v5h5"/></svg>');

// ---------------------------------------------------------------- themes
const THEMES = [
  { kind: 'suitcase', name: 'Weekend Trip', set: 'travel', bg: ['#fff3e3', '#ffd9c7'], shell: '#ff7d6b', lining: '#ffe6da', acc: '#ff6f61' },
  { kind: 'bento', name: 'Lunch Bento', set: 'food', bg: ['#fdf4e3', '#f5dcc0'], shell: '#f49ab0', lining: '#fff4f6', acc: '#e3678c' },
  { kind: 'backpack', name: 'School Day', set: 'travel', bg: ['#e6f4ff', '#cfe1ff'], shell: '#4f8ff7', lining: '#e2ecff', acc: '#3a74e0' },
  { kind: 'basket', name: 'Picnic Basket', set: 'food', bg: ['#eef9e6', '#d3efcf'], shell: '#e0a35a', lining: '#fff6e6', acc: '#3f9e62' },
  { kind: 'suitcase', name: 'Beach Escape', set: 'travel', bg: ['#e2fbf6', '#bfeee6'], shell: '#21b5a4', lining: '#ddf7f2', acc: '#16a394' },
  { kind: 'bento', name: 'Sushi Night', set: 'food', bg: ['#fff0ea', '#f7d0c6'], shell: '#3a3f5c', lining: '#fff4ea', acc: '#e05a47' },
  { kind: 'backpack', name: 'Camping Trip', set: 'travel', bg: ['#f1ebff', '#ddd0ff'], shell: '#8b6cf0', lining: '#efe9ff', acc: '#7655e0' },
  { kind: 'basket', name: 'Sunday Market', set: 'food', bg: ['#fff8dc', '#ffe7a8'], shell: '#c98a4b', lining: '#fff9ea', acc: '#d48a1e' },
];
const COLORS = ['#ff7a8a', '#ffb03b', '#5cc8a8', '#5aa7ff', '#a786ff', '#ff8fc8', '#7ed36b', '#ffd84d', '#4dd2e6', '#ff9d5c'];

// ---------------------------------------------------------------- level generation
function rngf(seed) { let s = (seed >>> 0) || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }
const K = (x, y) => x + ',' + y;
const N4 = [[1, 0], [-1, 0], [0, 1], [0, -1]];
const norm = (cells) => { const mx = Math.min(...cells.map(c => c[0])), my = Math.min(...cells.map(c => c[1])); return cells.map(([x, y]) => [x - mx, y - my]); };
const rotCells = (cells, k) => { let c = cells; for (let i = 0; i < k; i++) c = norm(c.map(([x, y]) => [-y, x])); return c; };
function connected(set) {
  const arr = [...set]; if (!arr.length) return true;
  const seen = new Set([arr[0]]), st = [arr[0]];
  while (st.length) { const [x, y] = st.pop().split(',').map(Number); for (const [a, b] of N4) { const k = K(x + a, y + b); if (set.has(k) && !seen.has(k)) { seen.add(k); st.push(k); } } }
  return seen.size === set.size;
}
function makeLevel(seed, lvl, fk) {
  const r = rngf(seed * 2654435761 + 97);
  for (let r0 = 0; r0 < 8; r0++) r();
  const n = Math.max(3, Math.min(9, Math.round((2.6 + lvl * 0.45) * fk)));
  const avg = lvl <= 2 ? 3 : lvl <= 5 ? 3.5 : 4;
  const target = Math.round(n * avg);
  for (let tries = 0; tries < 300; tries++) {
    let cols = Math.max(3, Math.min(7, Math.round(Math.sqrt(target * 1.1)) + (r() < 0.5 ? 0 : 1)));
    let rows = Math.max(2, Math.min(7, Math.ceil(target / cols)));
    if (cols * rows - target > Math.max(2, target * 0.3)) continue;
    const set = new Set(); for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) set.add(K(x, y));
    // carve cells from the edges (corners first) down to the target size: odd, cute case outlines
    let guard = 0;
    while (set.size > target && guard++ < 200) {
      const cand = [...set].filter(k => { const [x, y] = k.split(',').map(Number); return N4.filter(([a, b]) => set.has(K(x + a, y + b))).length <= 2; });
      const k = cand[Math.floor(r() * cand.length)]; set.delete(k);
      if (!connected(set)) set.add(k);
    }
    if (set.size !== target) continue;
    // keep the bounding box tight
    const cl = [...set].map(k => k.split(',').map(Number)), nc = norm(cl);
    const box = new Set(nc.map(([x, y]) => K(x, y)));
    cols = Math.max(...nc.map(c => c[0])) + 1; rows = Math.max(...nc.map(c => c[1])) + 1;
    // partition by compact random growth
    const owner = new Map(), cellsArr = [...box];
    const seeds = []; let pick = cellsArr[Math.floor(r() * cellsArr.length)]; seeds.push(pick);
    while (seeds.length < n) {
      let best = null, bd = -1;
      for (const c of cellsArr) { if (seeds.includes(c)) continue; const [x, y] = c.split(',').map(Number); const d = Math.min(...seeds.map(s => { const [a, b] = s.split(',').map(Number); return Math.abs(a - x) + Math.abs(b - y); })) + r() * 1.5; if (d > bd) { bd = d; best = c; } }
      seeds.push(best);
    }
    const regions = seeds.map((s, i) => { owner.set(s, i); return [s]; });
    const maxSz = lvl <= 2 ? 4 : 6;
    let stuck = 0;
    while (owner.size < box.size && stuck < 500) {
      const order = regions.map((R, i) => i).sort((a, b) => regions[a].length - regions[b].length + (r() - 0.5) * 0.9);
      let grew = false;
      for (const i of order) {
        if (regions[i].length >= maxSz) continue;
        const front = [];
        for (const c of regions[i]) { const [x, y] = c.split(',').map(Number); for (const [a, b] of N4) { const k = K(x + a, y + b); if (box.has(k) && !owner.has(k)) front.push(k); } }
        if (!front.length) continue;
        const score = (k) => { const [x, y] = k.split(',').map(Number); return N4.filter(([a, b]) => owner.get(K(x + a, y + b)) === i).length * 2 + r() * 1.6; };
        const k = front.sort((a, b) => score(b) - score(a))[0];
        owner.set(k, i); regions[i].push(k); grew = true; break;
      }
      if (!grew) stuck++;
      if (!grew) break;
    }
    if (owner.size < box.size) continue;
    if (regions.some(R => R.length < 1 || R.length > maxSz)) continue;
    if (regions.filter(R => R.length === 1).length > (lvl >= 3 ? 1 : 0)) continue;
    const theme = THEMES[(D.isDaily ? (seed % THEMES.length) : (lvl - 1)) % THEMES.length];
    const used = new Map();
    const pieces = regions.map((R, i) => {
      const abs = R.map(k => k.split(',').map(Number));
      const sx = Math.min(...abs.map(c => c[0])), sy = Math.min(...abs.map(c => c[1]));
      const cells = norm(abs), cls = classify(cells), opts = ITEMS[theme.set][cls];
      const u = used.get(cls) || 0; used.set(cls, u + 1);
      const item = opts[(u + Math.floor(r() * opts.length)) % opts.length];
      return { id: i, cells, cls, item, sol: { x: sx, y: sy }, color: COLORS[(i * 3 + Math.floor(r() * 10)) % COLORS.length], alt: COLORS[(i * 7 + 4) % COLORS.length], seed: Math.floor(r() * 9),
        w: Math.max(...cells.map(c => c[0])) + 1, h: Math.max(...cells.map(c => c[1])) + 1, rot: Math.floor(r() * 4), tilt: (r() - 0.5) * 0.22 };
    });
    // scatter order
    for (let k = pieces.length - 1; k > 0; k--) { const j = Math.floor(r() * (k + 1)); [pieces[k], pieces[j]] = [pieces[j], pieces[k]]; }
    return { box, cols, rows, pieces, theme };
  }
  return null;
}

// ---------------------------------------------------------------- state
let state = 'ready', level = S.get('level', 1), packed = S.get('packed', 0), lv = null, cs = 44, ox = 0, oy = 0, loops = null;
let drag = null, hist = [], closing = null, recorded = false, beatenShown = false, t0 = performance.now(), slips = 0, now = 0, squash = 0;
const P = () => lv.pieces;

function build() {
  const fk = D.isDaily ? 1 : F.k();
  const seed = D.seed ? D.seed : level * 7919 + 13;
  lv = makeLevel(seed, D.isDaily ? 9 : level, fk) || makeLevel(seed + 1, 3, 1);
  loops = outline([...lv.box].map(k => k.split(',').map(Number)));
  const th = lv.theme;
  document.body.style.setProperty('--ui', th.acc);
  for (const p of P()) { p.placed = null; p.angle = p.rot * Math.PI / 2 + p.tilt; p.sc = 0.2; p.flash = 0; p.wob = 0; p.bg = th.lining; }
  hist = []; closing = null; recorded = false; beatenShown = false; slips = 0; squash = 0; drag = null; t0 = performance.now();
  ui.levels(D.isDaily ? 1 : level); ui.sub(D.isDaily ? 'Daily · ' + th.name : th.name);
  if (D.isDaily) { ui.els.top.querySelector('[data-a]').textContent = '★'; ui.els.top.querySelector('[data-b]').textContent = '✓'; }
  layout(true); prog();
}
let tray = { x0: 0, y0: 0, x1: 0, y1: 0, s: 0.6 };
function layout(fresh) {
  const W = innerWidth, H = innerHeight, dpr = Math.min(devicePixelRatio || 1, 2);
  cv.width = W * dpr; cv.height = H * dpr; g.setTransform(dpr, 0, 0, dpr, 0, 0);
  const top = 92, bot = 84, zone = (H - top - bot) * 0.52, kind = lv.theme.kind;
  const hk = kind === 'basket' ? 1.45 : kind === 'suitcase' ? 1.05 : kind === 'backpack' ? 0.85 : 0.35;   // handle height + rim, in cells
  cs = Math.min(W > 700 ? 74 : 56, (Math.min(W, 620) - 70) / lv.cols, (zone - 24) / (lv.rows + hk + 0.4));
  ox = (W - lv.cols * cs) / 2; oy = top + hk * cs + Math.max(0, (zone - (lv.rows + hk + 0.4) * cs) / 2);
  const tw = Math.min(W - 20, 680);
  tray = { x0: (W - tw) / 2, x1: (W + tw) / 2, y0: oy + lv.rows * cs + 34, y1: H - bot };
  // shelf-pack the loose pieces into the tray at the largest scale that fits
  const loose = P();
  for (const s of [0.95, 0.85, 0.76, 0.68, 0.6, 0.54, 0.48, 0.42, 0.37]) {
    const gap = 14, rows = []; let row = { items: [], w: 0, h: 0 }, ok = true;
    for (const p of loose) {
      const rc = p.rot % 2 ? [p.h, p.w] : [p.w, p.h], pw = rc[0] * cs * s, ph = rc[1] * cs * s;
      if (row.items.length && row.w + gap + pw > tw - 10) { rows.push(row); row = { items: [], w: 0, h: 0 }; }
      row.items.push([p, pw, ph]); row.w += (row.items.length > 1 ? gap : 0) + pw; row.h = Math.max(row.h, ph);
    }
    rows.push(row);
    const th = rows.reduce((a, R) => a + R.h, 0) + gap * (rows.length - 1);
    if (th > tray.y1 - tray.y0 - 8 && s > 0.37) continue;
    let y = tray.y0 + Math.max(4, (tray.y1 - tray.y0 - th) / 2);
    for (const R of rows) {
      let x = (W - R.w) / 2;
      for (const [p, pw, ph] of R.items) { p.home = { x: x + pw / 2, y: y + R.h / 2 + (Math.sin(p.id * 2.3) * (R.h - ph) * 0.4), s }; x += pw + gap; }
      y += R.h + gap;
    }
    tray.s = s; break;
  }
  for (const p of P()) {
    if (p.placed) Object.assign(p, target(p, p.placed));
    else if (fresh) { p.x = p.home.x + (Math.random() - 0.5) * 30; p.y = p.home.y + 40; }
  }
  undoBtn.style.left = W / 2 - 70 + 'px'; resetBtn.style.left = W / 2 + 16 + 'px';
  undoBtn.style.bottom = resetBtn.style.bottom = `calc(16px + env(safe-area-inset-bottom))`;
}
addEventListener('resize', () => lv && layout(false));
const rcells = (p) => rotCells(p.cells, p.rot);
const rdims = (p) => (p.rot % 2 ? [p.h, p.w] : [p.w, p.h]);
function target(p, at) { const [rw, rh] = rdims(p); return { tx: ox + (at.x + rw / 2) * cs, ty: oy + (at.y + rh / 2) * cs }; }
function occ(except) { const m = new Map(); for (const p of P()) if (p.placed && p !== except) for (const [x, y] of rcells(p)) m.set(K(p.placed.x + x, p.placed.y + y), p); return m; }
function fits(p, at) { const o = occ(p); return rcells(p).every(([x, y]) => lv.box.has(K(at.x + x, at.y + y)) && !o.has(K(at.x + x, at.y + y))); }
function snapAt(p, cx, cy) { const [rw, rh] = rdims(p); return { x: Math.round((cx - rw * cs / 2 - ox) / cs), y: Math.round((cy - rh * cs / 2 - oy) / cs) }; }
function overCase(cx, cy) { return cx > ox - cs && cx < ox + (lv.cols + 1) * cs && cy > oy - cs && cy < oy + (lv.rows + 1) * cs; }
function filled() { return P().reduce((a, p) => a + (p.placed ? p.cells.length : 0), 0); }
function prog() { ui.progress(filled() / lv.box.size); }

// ---------------------------------------------------------------- moves
function place(p, at, push = true) {
  if (push) hist.push({ p, placed: p.placed, rot: p.rot });
  p.placed = at; p.wob = 1; p.tilt = 0;
  const t = target(p, at); p.tx = t.tx; p.ty = t.ty;
  const f = filled() / lv.box.size;
  soft.wood(); chime(Math.round(f * 7), 67, 0.11); buzz(8);
  const c = toScreen(p); fx.sparks(c.x, c.y, ['#fff', '#ffe08a', lv.theme.acc], 7, { speed: 2.6, size: 3 });
  prog();
  if (filled() === lv.box.size) finish();
}
function sendHome(p, push = true, bad = false) {
  if (push && p.placed) hist.push({ p, placed: p.placed, rot: p.rot });
  p.placed = null; p.tilt = (Math.random() - 0.5) * 0.18;
  if (bad) { p.flash = 1; soft.err(); buzz([10, 30, 10]); slips++; }
  prog();
}
const toScreen = (p) => ({ x: p.x, y: p.y });
function rotate(p) {
  const prev = { p, placed: p.placed, rot: p.rot };
  if (p.placed) {
    const [rw, rh] = rdims(p), cx = ox + (p.placed.x + rw / 2) * cs, cy = oy + (p.placed.y + rh / 2) * cs;
    p.rot = (p.rot + 1) % 4; const at = snapAt(p, cx, cy);
    hist.push(prev);
    if (fits(p, at)) { p.placed = at; const t = target(p, at); p.tx = t.tx; p.ty = t.ty; }
    else { p.placed = null; }
    prog();
  } else { hist.push(prev); p.rot = (p.rot + 1) % 4; }
  p.wob = 0.7; soft.swish(); tone(760, 0.06, 'triangle', 0.07, 1.3); buzz(5);
}

// ---------------------------------------------------------------- input
function local(p, px, py) {
  const s = (p === drag?.p ? 1 : p.sc) * cs, a = -p.angle, dx = px - p.x, dy = py - p.y;
  return [(dx * Math.cos(a) - dy * Math.sin(a)) / s + p.w / 2, (dx * Math.sin(a) + dy * Math.cos(a)) / s + p.h / 2, s];
}
function hitPiece(px, py) {
  const order = [...P()].sort((a, b) => (a.placed ? 0 : 1) - (b.placed ? 0 : 1));
  for (let i = order.length - 1; i >= 0; i--) {
    const p = order[i], [lx, ly, s] = local(p, px, py), tol = Math.max(0.12, 12 / s);
    if (p.cells.some(([x, y]) => lx > x - tol && lx < x + 1 + tol && ly > y - tol && ly < y + 1 + tol)) return p;
  }
  return null;
}
// the first seconds play themselves (Oct 26: under-1-minute players left within 10 s): on case 1, until the first real touch,
// a piece glides into the case at a spot that is NOT its answer, sits a beat and slides back out, so the drag-to-pack is shown
let demoP = null;
demo(n => {
  if (n === 1) {
    for (const p of P()) { if (p.placed) continue; for (let y = 0; y < lv.rows; y++) for (let x = 0; x < lv.cols; x++) if ((x !== p.sol.x || y !== p.sol.y || p.rot) && fits(p, { x, y })) { demoP = p; place(p, { x, y }, false); return; } }
    return false;
  }
  if (demoP && demoP.placed) sendHome(demoP, false); return false;
}, { ready: () => state === 'play' && level === 1 && !D.isDaily && !closing && !drag && (demoP ? !!demoP.placed : !P().some(p => p.placed)), wait: 1800, every: 1500, max: 2 });
cv.addEventListener('pointerdown', (e) => {
  if (state !== 'play' || closing || drag) return;
  const p = hitPiece(e.clientX, e.clientY); if (!p) return;
  cv.setPointerCapture(e.pointerId);
  const lift = e.pointerType === 'touch' ? 26 : 0;
  drag = { p, sx: e.clientX, sy: e.clientY, t: performance.now(), moved: false, offx: (p.x - e.clientX) / p.sc, offy: (p.y - e.clientY) / p.sc, lift, from: p.placed, px: e.clientX, py: e.clientY };
  soft.click(); tone(560, 0.05, 'sine', 0.08, 1.4);
});
cv.addEventListener('pointermove', (e) => {
  if (!drag) return; drag.px = e.clientX; drag.py = e.clientY;
  if (!drag.moved && Math.hypot(e.clientX - drag.sx, e.clientY - drag.sy) > 9) { drag.moved = true; if (drag.p.placed) { drag.p.placed = null; prog(); } drag.p.tilt = 0; }
});
const up = () => {
  if (!drag) return; const d = drag, p = d.p; drag = null;
  if (!d.moved) { if (performance.now() - d.t < 450) rotate(p); return; }
  const cx = p.x, cy = p.y, at = snapAt(p, cx, cy);
  if (fits(p, at)) { hist.push({ p, placed: d.from, rot: p.rot }); place(p, at, false); }
  else { if (d.from) hist.push({ p, placed: d.from, rot: p.rot }); sendHome(p, false, overCase(cx, cy)); }
};
cv.addEventListener('pointerup', up); cv.addEventListener('pointercancel', up);
undoBtn.addEventListener('click', (e) => {
  e.stopPropagation(); if (state !== 'play' || closing) return;
  const h = hist.pop(); if (!h) { soft.err(); return; }
  h.p.rot = h.rot; h.p.placed = null;
  if (h.placed && fits(h.p, h.placed)) { h.p.placed = h.placed; const t = target(h.p, h.placed); h.p.tx = t.tx; h.p.ty = t.ty; }
  h.p.wob = 0.6; soft.swish(); prog();
});
resetBtn.addEventListener('click', (e) => { e.stopPropagation(); if (state !== 'play' || closing) return; for (const p of P()) { p.placed = null; p.tilt = (Math.random() - 0.5) * 0.18; } hist = []; soft.swish(); prog(); });

// ---------------------------------------------------------------- win
function finish() {
  closing = { t: 0 };
  ui.pop(slips === 0 && hist.length <= lv.pieces.length + 2 ? 'PERFECT PACK!' : 'SNUG!', '#fff', 40, 28);
  arp([72, 76, 79], 70, 0.1, 0.5);
}
function win() {
  if (state !== 'play') return;
  state = 'won';
  if (!recorded) { recorded = true; B.submit(1, { ms: performance.now() - t0 }); if (!D.isDaily) F.level(true); }
  packed++; S.set('packed', packed);
  if (!beatenShown && D.beaten(packed)) { beatenShown = true; ui.pop('BEATEN!', '#fff', 40, 30); fx.confetti(60); }
  if (D.isDaily) S.set('daily_' + todayKey(), { done: 1 });
  else { level++; S.set('level', level); }
  D.won(packed, 'packed');
  ui.win(D.isDaily ? '' : level - 1, `${lv.pieces.length} things · ${lv.box.size} slots${slips === 0 ? ' · perfect' : ''}`);
}
ui.onTap((which) => {
  B.start();
  if (which === 'start') { state = 'play'; return; }
  if (which === 'win' && D.isDaily) { const u = new URL(location.href); u.search = ''; location.href = u.href; return; }
  build(); state = 'play';
});

// ---------------------------------------------------------------- drawing
function bgPaint(W, H) {
  const th = lv.theme, gr = g.createLinearGradient(0, 0, 0, H); gr.addColorStop(0, th.bg[0]); gr.addColorStop(1, th.bg[1]); g.fillStyle = gr; g.fillRect(0, 0, W, H);
  g.fillStyle = 'rgba(58,44,77,.06)';
  for (let y = 0, i = 0; y < H + 30; y += 30, i++) for (let x = (i % 2) * 15; x < W + 30; x += 30) { g.beginPath(); g.arc(x, y, 2.2, 0, 7); g.fill(); }
  // tray mat
  g.fillStyle = 'rgba(255,255,255,.45)'; g.beginPath(); g.roundRect(tray.x0, tray.y0 - 12, tray.x1 - tray.x0, tray.y1 - tray.y0 + 16, 26); g.fill();
}
function drawCase() {
  const th = lv.theme, lw = Math.max(3, cs * 0.08), pad = Math.max(10, cs * 0.3);
  const bw = lv.cols * cs, bh = lv.rows * cs;
  g.save(); g.translate(ox, oy);
  const sq = squash; g.translate(bw / 2, bh); g.scale(1 + sq * 0.06, 1 - sq * 0.06); g.translate(-bw / 2, -bh);
  // shadow
  g.save(); g.translate(0, lw * 2); roundPath(g, loops, cs, -pad, pad * 1.4); g.fillStyle = 'rgba(58,44,77,.18)'; g.fill(); g.restore();
  g.strokeStyle = INK; g.lineWidth = lw; g.lineJoin = 'round';
  // handle / straps behind the shell
  if (th.kind === 'suitcase' || th.kind === 'basket') {
    const hw = Math.min(bw * 0.5, cs * 2.4), hh = th.kind === 'basket' ? cs * 1.1 : cs * 0.7, x = bw / 2 - hw / 2;
    g.beginPath(); g.roundRect(x, -pad - hh, hw, hh + pad, [hh * 0.6, hh * 0.6, 0, 0]); g.fillStyle = shade(th.shell, -0.15); g.fill(); g.stroke();
    g.beginPath(); g.roundRect(x + lw * 2.2, -pad - hh + lw * 2.2, hw - lw * 4.4, hh + pad, [hh * 0.4, hh * 0.4, 0, 0]); g.fillStyle = th.bg[0]; g.fill(); g.stroke();
  } else if (th.kind === 'backpack') {
    const lw2 = cs * 0.9; g.beginPath(); g.roundRect(bw / 2 - lw2 / 2, -pad - cs * 0.55, lw2, cs * 0.8, cs * 0.4); g.fillStyle = shade(th.shell, -0.2); g.fill(); g.stroke();
  }
  // shell
  roundPath(g, loops, cs, -pad, pad * 1.4); g.fillStyle = th.shell; g.fill();
  if (th.kind === 'basket') { g.save(); g.clip(); g.strokeStyle = shade(th.shell, -0.18); g.lineWidth = 3; for (let k = -bh - 60; k < bw + bh + 60; k += 12) { g.beginPath(); g.moveTo(k, -pad); g.lineTo(k - bh - pad * 2, bh + pad); g.stroke(); g.beginPath(); g.moveTo(k, bh + pad); g.lineTo(k - bh - pad * 2, -pad); g.stroke(); } g.restore(); }
  if (th.kind === 'suitcase') { g.save(); g.clip(); g.fillStyle = shade(th.shell, -0.18); for (const fx of [0.28, 0.72]) g.fillRect(bw * fx - cs * 0.16, -pad - 4, cs * 0.32, bh + pad * 2 + 8); g.restore(); }
  g.strokeStyle = INK; g.lineWidth = lw; roundPath(g, loops, cs, -pad, pad * 1.4); g.stroke();
  // lining + slots
  roundPath(g, loops, cs, -2, cs * 0.22); g.fillStyle = th.lining; g.fill(); g.lineWidth = lw * 0.7; g.stroke();
  g.fillStyle = shade(th.lining, -0.07);
  for (const k of lv.box) { const [x, y] = k.split(',').map(Number); g.beginPath(); g.roundRect(x * cs + cs * 0.16, y * cs + cs * 0.16, cs * 0.68, cs * 0.68, cs * 0.16); g.fill(); }
  g.restore();
  // wheels / feet
  if (th.kind === 'suitcase') { g.fillStyle = INK; const by = oy + bh + pad + cs * 0.12; for (const x of [ox + cs * 0.5, ox + bw - cs * 0.5]) { g.beginPath(); g.arc(x, by, cs * 0.17, 0, 7); g.fill(); } }
}
function drawPiece(p, a = 1, ghost = null) {
  const s = ghost ? cs : (p === drag?.p ? 1 : p.sc) * cs;
  const x = ghost ? ghost.x : p.x, y = ghost ? ghost.y : p.y, ang = ghost ? p.rot * Math.PI / 2 : p.angle;
  const lp = outline(p.cells), lw = Math.max(2, s * 0.075), r = s * 0.24;
  g.save(); g.globalAlpha = a; g.translate(x, y); g.rotate(ang);
  const wob = p.wob || 0; if (!ghost && wob > 0.01) g.scale(1 + Math.sin(now * 0.03) * wob * 0.08, 1 - Math.sin(now * 0.03) * wob * 0.08);
  g.translate(-p.w * s / 2, -p.h * s / 2);
  if (ghost) { roundPath(g, lp, s, 3, r); g.fillStyle = ghost.ok ? 'rgba(255,255,255,.65)' : 'rgba(255,80,80,.35)'; g.fill(); g.setLineDash([6, 6]); g.strokeStyle = ghost.ok ? INK : '#e0465a'; g.lineWidth = 2.5; g.stroke(); g.restore(); return; }
  const lifted = p === drag?.p;
  g.save(); g.translate(0, lifted ? 10 : (p.placed ? 2 : 4)); roundPath(g, lp, s, 3, r); g.fillStyle = lifted ? 'rgba(58,44,77,.22)' : 'rgba(58,44,77,.16)'; g.fill(); g.restore();
  roundPath(g, lp, s, 3, r); g.fillStyle = fillOf(p); g.fill();
  g.save(); g.clip(); drawItem(g, p, s);
  // soft top highlight
  g.fillStyle = 'rgba(255,255,255,.14)'; g.fillRect(0, 0, p.w * s, s * 0.22);
  if (p.flash > 0.01) { g.fillStyle = `rgba(255,70,90,${p.flash * 0.55})`; g.fillRect(-4, -4, p.w * s + 8, p.h * s + 8); }
  g.restore();
  roundPath(g, lp, s, 3, r); g.strokeStyle = INK; g.lineWidth = lw; g.lineJoin = 'round'; g.stroke();
  g.restore();
}
function drawLid(t) {
  const th = lv.theme, lw = Math.max(3, cs * 0.08), pad = Math.max(10, cs * 0.3), bw = lv.cols * cs, bh = lv.rows * cs;
  const e = t < 1 ? 1 - Math.pow(1 - t, 3) : 1;
  g.save(); g.translate(ox, oy - pad);
  g.scale(1, Math.max(0.001, e)); g.translate(0, pad);
  roundPath(g, loops, cs, -pad, pad * 1.4); g.fillStyle = shade(th.shell, 0.08); g.fill();
  g.save(); g.clip();
  g.fillStyle = shade(th.shell, -0.15); if (th.kind === 'suitcase') for (const fx of [0.28, 0.72]) g.fillRect(bw * fx - cs * 0.16, -pad - 4, cs * 0.32, bh + pad * 2 + 8);
  else g.fillRect(-pad, bh * 0.45, bw + pad * 2, cs * 0.3);
  g.fillStyle = 'rgba(255,255,255,.18)'; g.fillRect(-pad, -pad, bw + pad * 2, (bh + pad * 2) * 0.18);
  g.restore();
  g.strokeStyle = INK; g.lineWidth = lw; roundPath(g, loops, cs, -pad, pad * 1.4); g.stroke();
  // latch
  if (t >= 1) { g.fillStyle = '#ffd84d'; g.beginPath(); g.roundRect(bw / 2 - cs * 0.35, bh + pad - cs * 0.45, cs * 0.7, cs * 0.5, cs * 0.12); g.fill(); g.stroke(); g.fillStyle = INK; g.beginPath(); g.arc(bw / 2, bh + pad - cs * 0.2, cs * 0.08, 0, 7); g.fill(); }
  g.restore();
}

let last = performance.now();
function frame(tms) {
  const dt = Math.max(0, Math.min(2.5, (tms - last) / 16.67)); last = tms; now = tms;
  const W = innerWidth, H = innerHeight;
  if (lv) {
    for (const p of P()) {
      if (drag && drag.p === p) {
        const tx = drag.px + drag.offx, ty = drag.py + drag.offy - (drag.moved ? drag.lift : 0);
        p.x += (tx - p.x) * Math.min(1, 0.6 * dt); p.y += (ty - p.y) * Math.min(1, 0.6 * dt); p.sc += (1 - p.sc) * 0.3 * dt;
      } else if (p.placed) { const t = target(p, p.placed); p.x += (t.tx - p.x) * Math.min(1, 0.32 * dt); p.y += (t.ty - p.y) * Math.min(1, 0.32 * dt); p.sc += (1 - p.sc) * 0.3 * dt; }
      else { p.x += (p.home.x - p.x) * Math.min(1, 0.2 * dt); p.y += (p.home.y - p.y) * Math.min(1, 0.2 * dt); p.sc += (p.home.s - p.sc) * 0.25 * dt; }
      const ta = p.rot * Math.PI / 2 + (p.placed || (drag && drag.p === p) ? 0 : p.tilt);
      let da = ta - p.angle; da = Math.atan2(Math.sin(da), Math.cos(da)); p.angle += da * Math.min(1, 0.3 * dt);
      p.wob *= Math.pow(0.9, dt); p.flash *= Math.pow(0.92, dt);
    }
    squash *= Math.pow(0.86, dt);
    bgPaint(W, H); drawCase();
    for (const p of P()) if (p.placed && !(drag && drag.p === p)) drawPiece(p);
    if (drag && drag.moved) {
      const p = drag.p, at = snapAt(p, p.x, p.y), ok = fits(p, at);
      if (ok || overCase(p.x, p.y)) { const t = target(p, at); drawPiece(p, 1, { x: t.tx, y: t.ty, ok }); }
    }
    for (const p of P()) if (!p.placed && !(drag && drag.p === p)) drawPiece(p);
    if (drag) drawPiece(drag.p);
    if (closing) {
      closing.t += dt / 26;
      drawLid(Math.min(1, closing.t));
      if (closing.t >= 1 && !closing.clicked) { closing.clicked = true; squash = 1; tone(1900, 0.04, 'square', 0.08, 0.7); setTimeout(() => tone(1300, 0.05, 'square', 0.07, 0.8), 70); buzz([15, 40, 25]); fx.confetti(120); arp([67, 72, 76, 79, 84], 90, 0.12, 0.8); fx.sparks(W / 2, oy + lv.rows * cs, ['#ffd84d', '#fff', lv.theme.acc], 22, { speed: 6, size: 4 }); }
      if (closing.t >= 1.5 && state === 'play') win();
    }
  }
  requestAnimationFrame(frame);
}
build();
requestAnimationFrame(frame);

let botAt = 0;
// ---------------------------------------------------------------- test hook: the bot packs one piece per call at its solution spot
window.__game = {
  get state() { return state; }, get level() { return level; }, get score() { return packed; },
  bot() {
    if (state !== 'play' || closing || drag) return;
    const tb = performance.now(); if (tb - botAt < 700) return; botAt = tb;   // human pace: one piece every ~0.7 s
    const p = P().find(q => !(q.placed && q.rot === 0 && q.placed.x === q.sol.x && q.placed.y === q.sol.y)); if (!p) return;
    p.rot = 0;
    const want = new Set(p.cells.map(([x, y]) => K(p.sol.x + x, p.sol.y + y)));
    for (const q of P()) if (q !== p && q.placed && rcells(q).some(([x, y]) => want.has(K(q.placed.x + x, q.placed.y + y)))) sendHome(q, false);
    if (p.placed) p.placed = null;
    place(p, { ...p.sol });
  },
};
